from datetime import datetime, timedelta
import json
from unittest.mock import patch

import api_client
import api_server
import config
import database
import importers
import support


CATALOGUE_ID = 'reviewed-api-fixture-one'
PROOF_URL = 'https://sportangebot.unisg.ch/public-discovery-schedule?selectedDate=2026-11-03'
PROOF_TIME = '2026-11-02 09:00:00'


def response(status, payload, headers=None):
    """Build a requests response including identity headers without opening a socket."""
    result = api_client.requests.Response()
    result.status_code = status
    result._content = json.dumps(payload).encode('utf-8')
    result._content_consumed = True
    if headers:
        result.headers.update(headers)
    return result


class ApiProvenanceTests(support.DatabaseCase):
    """Route requests through Flask against two independent databases with colliding IDs."""

    def setUp(self):
        """Seed published, projected and legacy rows in a reviewed shared-memory catalogue."""
        super().setUp()
        uri = f'file:api-proof-{self._testMethodName}?mode=memory&cache=shared'
        anchor = database.get_connection(uri, uri=True)
        self.connection.backup(anchor)
        self.connection.close()
        self.connection = anchor
        self.addCleanup(anchor.close)
        clock = patch.object(config, 'local_now', side_effect=lambda now=None: now or support.NOW)
        clock.start()
        self.addCleanup(clock.stop)
        self.user = database.create_user(self.connection, 'Alex', now=support.NOW)
        for offset, title, status in ((1, 'Published Tennis', 'unknown'),
                                      (2, 'Projected Yoga', 'unknown'),
                                      (3, 'Legacy Running', 'open')):
            start = support.NOW + timedelta(days=offset)
            record = support.record(source='unisport', external_id=title, title=title,
                                    club_name='', club_category='', sport=title, price=None,
                                    start=start, end=start + timedelta(hours=1), status=status)
            importers.save_records(self.connection, [record], 'unisport', self.taxonomy,
                                   now=support.NOW)
        self.ids = [row['id'] for row in self.connection.execute(
            'SELECT id FROM events ORDER BY id')]
        for event_id, kind in zip(self.ids, ('website', 'projected')):
            with self.connection:
                self.connection.execute('''INSERT INTO event_provenance
                    (event_id,kind,forecast_anchor_date,evidence_weeks,created_at,
                     verification_url,verified_at) VALUES (?,?,?,?,?,?,?)''',
                    (event_id, kind, '2026-10-30', 3, PROOF_TIME,
                     PROOF_URL if kind == 'website' else None,
                     PROOF_TIME if kind == 'website' else None))
        database.set_setting(self.connection, 'catalogue_mode', config.REVIEWED_CATALOGUE_MODE)
        database.set_setting(self.connection, 'catalogue_id', CATALOGUE_ID)
        self.client = api_server.create_app(uri, uri=True).test_client()
        self.remote_client = self.client
        self.start, self.end = datetime(2026, 11, 3), datetime(2026, 11, 6)
        self.params = {'from': '2026-11-03', 'to': '2026-11-06'}
        self.headers = {config.API_CATALOGUE_HEADER: CATALOGUE_ID}

    def bridge_get(self, url, params=None, **options):
        """Forward identity in both directions while exercising actual Flask routes."""
        self.assertEqual(options['timeout'], config.API_TIMEOUT_SECONDS)
        self.assertFalse(options['allow_redirects'])
        result = self.remote_client.get(url.removeprefix(config.API_BASE_URL),
                                        query_string=params, headers=options.get('headers', {}))
        return response(result.status_code, result.json, dict(result.headers))

    def bridge_post(self, url, json=None, **options):
        """Apply the real state machine only after the server checks the requested catalogue."""
        self.assertEqual(url, config.API_BASE_URL + '/interactions')
        self.assertEqual(options['timeout'], config.API_TIMEOUT_SECONDS)
        self.assertFalse(options['allow_redirects'])
        result = self.remote_client.post('/interactions', json=json,
                                         headers=options.get('headers', {}))
        return response(result.status_code, result.json, dict(result.headers))

    def body(self, event_id=None):
        """Use the bookable legacy row unless a particular unknown-status row is requested."""
        return {'user_id': self.user, 'event_id': self.ids[-1] if event_id is None else event_id,
                'action': 'confirm', 'rating': None}

    def rows(self):
        """Read the expected fixed public row contract directly from local SQLite."""
        return database.get_event_records(self.connection, self.start, self.end)

    def other_catalogue(self):
        """Clone colliding IDs into an independent catalogue that must not receive local writes."""
        uri = f'file:api-proof-other-{self._testMethodName}?mode=memory&cache=shared'
        other = database.get_connection(uri, uri=True)
        self.addCleanup(other.close)
        self.connection.backup(other)
        database.set_setting(other, 'catalogue_id', 'reviewed-api-fixture-other')
        with other:
            other.execute('UPDATE series SET title=?', ('Only in the other catalogue',))
        self.remote_client = api_server.create_app(uri, uri=True).test_client()
        return other

    def test_http_and_fallback_share_every_provenance_value(self):
        """List and single-event HTTP paths preserve all five fields and exact nullable types."""
        result = self.client.get('/events', query_string=self.params)
        self.assertEqual(result.status_code, 200)
        self.assertEqual(result.json, self.rows())
        self.assertEqual(result.headers[config.API_CATALOGUE_HEADER], CATALOGUE_ID)
        with patch.object(api_client.requests, 'get', side_effect=self.bridge_get):
            remote, origin = api_client.get_events(self.start, self.end, connection=self.connection)
            self.assertEqual(origin, 'api')
            local, local_origin = api_client.get_events(self.start, self.end, False,
                                                         self.connection)
            self.assertEqual(local_origin, 'database')
            self.assertEqual([event.__dict__ for event in remote],
                             [event.__dict__ for event in local])
            for expected in local:
                event, single_origin = api_client.get_event(expected.event_id,
                                                            connection=self.connection)
                self.assertEqual(single_origin, 'api')
                self.assertEqual(event.__dict__, expected.__dict__)
        self.assertEqual([event.provenance_kind for event in remote],
                         ['website', 'projected', None])
        self.assertIs(type(remote[0].evidence_weeks), int)
        self.assertIsNone(remote[-1].evidence_weeks)

    def test_complete_legacy_dto_is_unspecified_without_an_expected_catalogue(self):
        """A complete old response remains readable without inventing website evidence."""
        legacy = []
        for row in self.rows():
            legacy.append({field: row[field] for field in config.LEGACY_EVENT_RECORD_FIELDS})
        with patch.object(api_client.requests, 'get', return_value=response(200, legacy)), \
                patch.object(database, 'get_connection', side_effect=AssertionError('No fallback')):
            events, origin = api_client.get_events(self.start, self.end)
        self.assertEqual(origin, 'api')
        self.assertEqual(len(events), 3)
        for event in events:
            for field in config.EVENT_PROVENANCE_FIELDS:
                self.assertIsNone(getattr(event, field))

    def test_partial_new_metadata_falls_back_to_complete_local_proof(self):
        """An old field set with one new provenance key is malformed rather than partly trusted."""
        malformed = {field: self.rows()[0][field] for field in config.LEGACY_EVENT_RECORD_FIELDS}
        malformed['provenance_kind'] = 'website'
        with patch.object(api_client.requests, 'get',
                           return_value=response(200, [malformed], self.headers)):
            events, origin = api_client.get_events(self.start, self.end, connection=self.connection)
        self.assertEqual(origin, 'database')
        self.assertEqual(events[0].verification_url, PROOF_URL)
        self.assertEqual(events[0].verified_at, PROOF_TIME)

    def test_malformed_proof_uses_unmodified_local_records(self):
        """Fractional/bool weeks and contradictory or undated proof cannot replace local data."""
        baseline = self.rows()
        changes = ({'evidence_weeks': 3.5}, {'evidence_weeks': True},
                   {'provenance_kind': 'projected', 'verification_url': PROOF_URL},
                   {'verified_at': '2026-02-30 12:00:00'})
        for change in changes:
            with self.subTest(change=change):
                malformed = baseline[0].copy()
                malformed.update(change)
                with patch.object(api_client.requests, 'get',
                                   return_value=response(200, [malformed], self.headers)):
                    events, origin = api_client.get_events(self.start, self.end,
                                                           connection=self.connection)
                self.assertEqual(origin, 'database')
                self.assertEqual(events[0].verified_at, PROOF_TIME)
                with patch.object(api_client.requests, 'get',
                                   return_value=response(200, malformed, self.headers)):
                    event, origin = api_client.get_event(self.ids[0], connection=self.connection)
                self.assertEqual(origin, 'database')
                self.assertEqual(event.evidence_weeks, 3)
                self.assertEqual(self.rows(), baseline)

    def test_wrong_catalogue_get_uses_local_list_and_single_event(self):
        """Colliding event IDs in another database cannot substitute their titles or evidence."""
        other = self.other_catalogue()
        with patch.object(api_client.requests, 'get', side_effect=self.bridge_get):
            events, origin = api_client.get_events(self.start, self.end, connection=self.connection)
            event, single_origin = api_client.get_event(self.ids[0], connection=self.connection)
        self.assertEqual((origin, single_origin), ('database', 'database'))
        self.assertEqual(events[0].title, 'Published Tennis')
        self.assertEqual(event.title, 'Published Tennis')
        self.assertEqual(other.execute('SELECT COUNT(*) FROM interactions').fetchone()[0], 0)

    def test_wrong_catalogue_post_never_writes_the_other_database(self):
        """A failed preflight prevents a write to a database with colliding event and user IDs."""
        other = self.other_catalogue()
        with patch.object(api_client.requests, 'get', side_effect=self.bridge_get) as get, \
                patch.object(api_client.requests, 'post', side_effect=self.bridge_post) as post:
            stored, origin = api_client.save_interaction(self.user, self.ids[-1], 'confirm',
                                                        connection=self.connection)
        self.assertEqual((stored['status'], origin), ('confirmed', 'database'))
        self.assertEqual(get.call_count, 1)
        post.assert_not_called()
        self.assertEqual(other.execute('SELECT COUNT(*) FROM interactions').fetchone()[0], 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 1)

    def test_reviewed_client_write_checks_identity_then_uses_matching_api(self):
        """A matching preflight permits one POST and retains the normal shared state machine."""
        with patch.object(api_client.requests, 'get', side_effect=self.bridge_get) as get, \
                patch.object(api_client.requests, 'post', side_effect=self.bridge_post) as post:
            stored, origin = api_client.save_interaction(self.user, self.ids[-1], 'confirm',
                                                        connection=self.connection)
        self.assertEqual((stored['status'], origin), ('confirmed', 'api'))
        self.assertEqual((get.call_count, post.call_count), (1, 1))
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 1)

    def test_reviewed_legacy_server_without_identity_receives_no_post(self):
        """A stale healthy hint cannot send a write to an old server that ignores identity."""
        health = {'status': 'ok', 'version': config.APP_VERSION}
        with patch.object(api_client.requests, 'get', return_value=response(200, health)) as get, \
                patch.object(api_client.requests, 'post') as post:
            stored, origin = api_client.save_interaction(self.user, self.ids[-1], 'confirm',
                                                        connection=self.connection)
        self.assertEqual((stored['status'], origin), ('confirmed', 'database'))
        self.assertEqual(get.call_count, 1)
        self.assertEqual(get.call_args.kwargs['headers'], self.headers)
        post.assert_not_called()
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 1)

    def test_known_catalogue_requires_identity_even_for_demo(self):
        """An old API that omits identity cannot satisfy an explicitly identified local dataset."""
        for catalogue_id in (CATALOGUE_ID, config.DEFAULT_CATALOGUE_ID):
            with self.subTest(catalogue_id=catalogue_id):
                database.set_setting(self.connection, 'catalogue_id', catalogue_id)
                with patch.object(api_client.requests, 'get',
                                   return_value=response(200, self.rows())):
                    events, origin = api_client.get_events(self.start, self.end,
                                                           connection=self.connection)
                self.assertEqual(origin, 'database')
                self.assertEqual(len(events), 3)

    def test_health_json_stays_compatible_and_identity_is_checked(self):
        """Health retains its JSON shape while matching or rejecting the catalogue header."""
        result = self.client.get('/health')
        self.assertEqual(result.json, {'status': 'ok', 'version': config.APP_VERSION})
        self.assertEqual(result.headers[config.API_CATALOGUE_HEADER], CATALOGUE_ID)
        with patch.object(api_client.requests, 'get', side_effect=self.bridge_get):
            self.assertTrue(api_client.is_api_available(CATALOGUE_ID))
            self.assertFalse(api_client.is_api_available('different-catalogue'))
        with patch.object(api_client.requests, 'get', return_value=response(200, result.json)):
            self.assertFalse(api_client.is_api_available(CATALOGUE_ID))
            self.assertTrue(api_client.is_api_available())

    def test_reviewed_writes_require_identity_and_mismatch_precedes_mutation(self):
        """Read-only public requests are allowed, but unidentified or wrong writes return 409."""
        self.assertEqual(self.client.get('/events', query_string=self.params).status_code, 200)
        missing = self.client.post('/interactions', json=self.body())
        wrong = self.client.post('/interactions', json=self.body(),
                                 headers={config.API_CATALOGUE_HEADER: 'wrong'})
        self.assertEqual((missing.status_code, wrong.status_code), (409, 409))
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 0)
        accepted = self.client.post('/interactions', json=self.body(), headers=self.headers)
        self.assertEqual(accepted.status_code, 201)
        self.assertEqual(accepted.headers[config.API_CATALOGUE_HEADER], CATALOGUE_ID)

    def test_published_and_projected_unknown_availability_cannot_be_confirmed(self):
        """Publication evidence cannot bypass the existing unknown-availability state guard."""
        for event_id in self.ids[:2]:
            with self.subTest(event_id=event_id):
                result = self.client.post('/interactions', json=self.body(event_id),
                                          headers=self.headers)
                self.assertEqual(result.status_code, 400)
                self.assertIn('availability', result.json['error'])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 0)

    def test_public_endpoints_do_not_expose_archive_or_profile_fields(self):
        """Only selected occurrence columns are returned; no private-table route is added."""
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 0)
        result = self.client.get('/events', query_string=self.params)
        self.assertEqual(set(result.json[0]), set(config.EVENT_RECORD_FIELDS))
        for forbidden in ('PRIVATE-EXPORT', 'source_fingerprint', 'participants_signed_up',
                          'friend_code', 'sharing_opt_in'):
            self.assertNotIn(forbidden, result.get_data(as_text=True))
        self.assertEqual(self.client.get('/training_history').status_code, 404)
        self.assertEqual(self.client.get('/training_imports').status_code, 404)

    def add_private_archive(self):
        """Populate one synthetic private source row solely to test the refused serving boundary."""
        with self.connection:
            self.connection.execute('''INSERT INTO training_imports
                (id,file_name,source_fingerprint,imported_at) VALUES (61,?,?,?)''',
                ('PRIVATE-EXPORT-NOT-PUBLIC.csv', 'private-api-test-hash', PROOF_TIME))
            self.connection.execute('''INSERT INTO training_history
                (import_id,source_row,sport,weekday_text,start_time,date_original,training_date)
                VALUES (61,2,'PRIVATE ARCHIVE TEXT','Friday','08:00',
                        'Freitag, 30. Oktober 2026','2026-10-30')''')

    def test_raw_archive_is_refused_before_health_events_or_writes(self):
        """An accidental raw-archive target returns 503 without leaking rows or changing data."""
        self.add_private_archive()
        baseline = self.rows()
        results = [self.client.get('/health'),
                   self.client.get('/events', query_string=self.params),
                   self.client.get(f'/events/{self.ids[0]}'),
                   self.client.post('/interactions', json=self.body(), headers=self.headers)]
        for result in results:
            self.assertEqual(result.status_code, 503)
            self.assertIn('error', result.json)
            for forbidden in ('PRIVATE', 'Published Tennis', 'private-api-test-hash'):
                self.assertNotIn(forbidden, result.get_data(as_text=True))
        self.assertEqual(self.rows(), baseline)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 1)

    def test_source_refresh_keeps_reviewed_catalogue_and_private_archive_unchanged(self):
        """Both protected modes skip candidate loads, private source reads and import logging."""
        for mode in ('reviewed', 'archive'):
            with self.subTest(mode=mode):
                if mode == 'archive':
                    self.add_private_archive()
                    database.set_setting(self.connection, 'catalogue_mode', 'demo')
                baseline = self.rows()
                proofs = [tuple(row) for row in self.connection.execute(
                    'SELECT * FROM event_provenance ORDER BY event_id')]
                log_count = self.scalar('SELECT COUNT(*) FROM import_log')
                with patch.object(importers, '_load_candidate') as load, \
                        patch.object(importers, 'read_private_sources') as read_private:
                    reports = importers.import_all(self.connection, self.taxonomy,
                                                   now=support.NOW, **self.paths)
                self.assertEqual(len(reports), len(config.SOURCES))
                self.assertTrue(all(report['outcome'] == 'ok' for report in reports))
                load.assert_not_called()
                read_private.assert_not_called()
                self.assertEqual(self.rows(), baseline)
                self.assertEqual([tuple(row) for row in self.connection.execute(
                    'SELECT * FROM event_provenance ORDER BY event_id')], proofs)
                self.assertEqual(self.scalar('SELECT COUNT(*) FROM import_log'), log_count)
